def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts: dict[str, list] = {}  # name -> [balance, frozen]
    history: list[dict] = []  # name -> previous (balance, frozen), or None if the account did not exist
    rejected: list[int] = []

    def parse_amount(tok):
        if not tok or any(c not in "0123456789" for c in tok):
            return None
        return int(tok)

    def snapshot(*names):
        return {n: (tuple(accounts[n]) if n in accounts else None) for n in names}

    for idx, op in enumerate(ops):
        tokens = op.split(" ")
        verb, args = tokens[0], tokens[1:]
        ok = False
        record = None

        if verb == "undo" and len(args) == 0:
            if history:
                for name, prev in history.pop().items():
                    if prev is None:
                        accounts.pop(name, None)
                    else:
                        accounts[name] = list(prev)
                ok = True

        elif verb == "open" and len(args) == 2:
            name, amt = args[0], parse_amount(args[1])
            if amt is not None and name not in accounts:
                record = snapshot(name)
                accounts[name] = [amt, False]
                ok = True

        elif verb == "deposit" and len(args) == 2:
            name, amt = args[0], parse_amount(args[1])
            if amt is not None and amt > 0 and name in accounts:
                record = snapshot(name)
                accounts[name][0] += amt
                ok = True

        elif verb == "withdraw" and len(args) == 2:
            name, amt = args[0], parse_amount(args[1])
            if (amt is not None and amt > 0 and name in accounts
                    and not accounts[name][1] and accounts[name][0] >= amt):
                record = snapshot(name)
                accounts[name][0] -= amt
                ok = True

        elif verb == "transfer" and len(args) == 3:
            src, dst, amt = args[0], args[1], parse_amount(args[2])
            if (amt is not None and amt > 0 and src != dst
                    and src in accounts and dst in accounts
                    and not accounts[src][1] and accounts[src][0] >= amt):
                record = snapshot(src, dst)
                accounts[src][0] -= amt
                accounts[dst][0] += amt
                ok = True

        elif verb == "freeze" and len(args) == 1:
            name = args[0]
            if name in accounts and not accounts[name][1]:
                record = snapshot(name)
                accounts[name][1] = True
                ok = True

        elif verb == "unfreeze" and len(args) == 1:
            name = args[0]
            if name in accounts and accounts[name][1]:
                record = snapshot(name)
                accounts[name][1] = False
                ok = True

        if ok:
            if verb != "undo":
                history.append(record)
        else:
            rejected.append(idx)

    return {name: state[0] for name, state in accounts.items()}, rejected
